if (all(lessThan(abs(Color.rgb * 255.0 - vec3(254.0, 1.0, 2.0)), vec3(0.5)))) {
    // Screen position of this vertex, 0..1, in the same orientation as gl_Position.
    vec2 screen = clamp(gl_Position.xy / gl_Position.w * 0.5 + 0.5, 0.0, 1.0);
    // 16 bits per axis, as two 8-bit channels each.
    vec2 value = round(screen * 65535.0);
    vec2 hi = floor(value / 256.0);
    markerData = vec4(hi.x, value.x - hi.x * 256.0, hi.y, value.y - hi.y * 256.0) / 255.0;
    markerKind = 1;
    // Move the vertex onto a 3x1-pixel strip in the corner at NDC (-1, -1), in front of everything
    // (reversed depth: NDC z close to 1 is near).
    // Corners in this order keep the quad front-facing: the pipeline culls back faces.
    int corner = gl_VertexIndex % 4;
    vec2 cornerPos = vec2(corner == 1 || corner == 2 ? 3.0 : 0.0, corner == 2 || corner == 3 ? 1.0 : 0.0);
    gl_Position = vec4(-1.0 + 2.0 * cornerPos / ScreenSize, 0.999, 1.0);
}

