#version 330
#extension GL_ARB_separate_shader_objects : require

// Full-screen triangle for post passes: the same as vanilla core/screenquad (26.3) and
// core/screentriangle (26.4), shipped with the pack so it does not depend on either.
layout(location = 0) out vec2 texCoord;

void main() {
    vec2 uv = vec2((gl_VertexIndex << 1) & 2, gl_VertexIndex & 2);
    gl_Position = vec4(uv * 2.0 - 1.0, 0.0, 1.0);
    texCoord = uv;
}

#version 330
#extension GL_ARB_separate_shader_objects : require

uniform sampler2D InSampler;

layout(std140) uniform SamplerInfo {
    vec2 OutSize;
    vec2 InSize;
};

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

bool isMarker(ivec2 p) {
    vec3 c = texelFetch(InSampler, p, 0).rgb;
    return all(lessThan(abs(c - vec3(1.0, 0.0, 1.0)), vec3(0.01)));
}

float decode(vec2 bytes) {
    vec2 b = round(bytes * 255.0);
    return (b.x * 256.0 + b.y) / 65535.0;
}

void main() {
    ivec2 size = ivec2(InSize);
    ivec2 pixel = ivec2(texCoord * InSize);
    vec3 color = texture(InSampler, texCoord).rgb;

    // The strip is in the bottom row or the top row, depending on how gl_Position maps to this texture.
    int row = isMarker(ivec2(0, 0)) ? 0 : isMarker(ivec2(0, size.y - 1)) ? size.y - 1 : -1;
    if (row >= 0) {
        // Hide the strip: copy the row next to it.
        if (pixel.y == row && pixel.x < 3) {
            color = texelFetch(InSampler, ivec2(pixel.x, row == 0 ? 1 : row - 1), 0).rgb;
        }
        vec2 anchor = vec2(decode(texelFetch(InSampler, ivec2(1, row), 0).rg), decode(texelFetch(InSampler, ivec2(2, row), 0).rg));
        if (row != 0) {
            anchor.y = 1.0 - anchor.y;   // the strip landed in the top row: flip to texCoord's orientation
        }
        // A ring 40 pixels across around the anchor.
        float d = length((texCoord - anchor) * InSize);
        float ring = smoothstep(3.0, 1.0, abs(d - 40.0));
        color = mix(color, vec3(1.0, 0.6, 0.1), ring);
    }
    fragColor = vec4(color, 1.0);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

uniform sampler2D InSampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    fragColor = vec4(texture(InSampler, texCoord).rgb, 1.0);
}
